 */
public Cookie(@NonNull
String name) {
    this(name, null);
}

private Cookie(@NonNull
Cookie cookie) {
    this.domain = cookie.domain;
    this.value = cookie.value;
    this.name = cookie.name;
    this.maxAge = cookie.maxAge;
    this.path = cookie.path;
    this.secure = cookie.secure;
    this.httpOnly = cookie.httpOnly;
    this.sameSite = cookie.sameSite;
}

/**
 * Creates a session cookie which never expires (maxAge: -1), is http only and path is <code>/
 * </code>.
 *
 * @param sid
 * 		Session ID.
 * @return Session's cookie.
 */
public static Cookie session(@NonNull
String sid) {
    return new Cookie(sid).setMaxAge(-1).setHttpOnly(true).setPath("/");
}

